 await nextTick();edited.value=false;checked.value=false;heard.value=false;quiet.value=false;changed();
 });}
async function recheckRun(){await action(async()=>{checked.value=false;heard.value=false;const r=runner.value;if(!r)return;await r.bank.unlock();await r.bank.preflight(r.session.project,s=>info.value=s);await r.bank.tone(r.session.project.config.playbackVolume??1);checked.value=true;info.value=localizedMessage('modules.perception.text.3e7faddc32ad');});}
