function down(e:KeyboardEvent){
 const r=runner.value;if(!props.active||stage.value!=='run'||!r||busy.value||e.key==='Tab')return;
 const target=e.target as Element|null;
 if(target?.closest?.('input,select,textarea,a,[contenteditable=true]')||target?.closest?.('button')&&!target.closest('[data-m15-advance]'))return;
 if(!r.focused&&!(r.phase==='intro'&&isContinueKey(e)))return;
 e.preventDefault();e.stopImmediatePropagation();
 if(e.key==='Escape'&&isCleanKey(e)&&r.focused){void action(()=>r.interrupt('manual-pause','手动暂停').then(()=>{}));return;}
 r.keydown(e,()=>{void continueRun();});
}
